import{_ as i,a0 as r,w as a,s as m,I as n,x as o,a1 as e,A as l,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"NMAP 常用扫描简介（二） | LCTT x X-CMD","titleTemplate":false,"description":"NMAP 常用扫描简介（二） | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NMAP 常用扫描简介（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NMAP 常用扫描简介（二） | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170125 NMAP Common Scans – Part Two","title":"NMAP 常用扫描简介（二）","tag":"201704","desc":""},"relativePath":"201704/20170125 NMAP Common Scans – Part Two.md","filePath":"[post].md"}'),P={name:"201704/20170125 NMAP Common Scans – Part Two.md"};function C(T,t,d,u,N,S){const p=r("Link");return a(),m("div",null,[t[19]||(t[19]=n("h1",{id:"nmap-常用扫描简介-二",tabindex:"-1"},[o("NMAP 常用扫描简介（二） "),n("a",{class:"header-anchor",href:"#nmap-常用扫描简介-二","aria-label":"Permalink to “NMAP 常用扫描简介（二）”"},"​")],-1)),n("p",null,[t[1]||(t[1]=o("在我们之前的 ",-1)),e(p,{href:"https://www.linuxforum.com/threads/nmap-installation.3431/"},{default:l(()=>[...t[0]||(t[0]=[o("NMAP 安装",-1)])]),_:1}),t[2]||(t[2]=o("一文中，列出了 10 种不同的 ZeNMAP 扫描模式，大多数的模式使用了不同的参数。各种不同参数代表执行不同的扫描模式。这篇文章将介绍最后剩下的两种常用扫描类型。",-1))]),t[20]||(t[20]=s('<h3 id="四种通用扫描类型" tabindex="-1">四种通用扫描类型 <a class="header-anchor" href="#四种通用扫描类型" aria-label="Permalink to “四种通用扫描类型”">​</a></h3><p>下面列出了最常用的四种扫描类型：</p><ol><li>PING 扫描（<code>-sP</code>）</li><li>TCP SYN 扫描（<code>-sS</code>）</li><li>TCP Connect() 扫描（<code>-sT</code>）</li><li>UDP 扫描（<code>-sU</code>）</li></ol><p>当我们利用 NMAP 来执行扫描的时候，这四种扫描类型是我们需要熟练掌握的。更重要的是需要知道这些命令做了什么，并且需要知道这些命令是怎么做的。在这篇文章中将介绍两种 TCP 扫描 — TCP SYN 扫描和 TCP Connect() 扫描。</p>',4)),n("p",null,[t[4]||(t[4]=o("(",-1)),e(p,{href:"https://linux.cn/article-8346-1.html%EF%BC%8F"},{default:l(()=>[...t[3]||(t[3]=[o("阅读 NMAP 常用扫描简介（一）",-1)])]),_:1}),t[5]||(t[5]=o(")",-1))]),t[21]||(t[21]=s('<h3 id="tcp-syn-扫描-ss" tabindex="-1">TCP SYN 扫描 （-sS） <a class="header-anchor" href="#tcp-syn-扫描-ss" aria-label="Permalink to “TCP SYN 扫描 （-sS）”">​</a></h3><p>TCP SYN 扫描是默认的 NMAP 扫描方式。为了运行 TCP SYN 扫描，你需要有 Root 权限。</p><p>TCP SYN 扫描的目的是找到被扫描系统上的已开启端口。使用 NMAP 扫描可以扫描在防火墙另一侧的系统。当扫描通过防火墙时，扫描时间会延长，因为数据包会变慢。</p><p>TCP SYN 扫描的工作方式是启动一个“三次握手”。正如在另一篇文章中所述，“三次握手”发生在两个系统之间。首先，源系统发送一个包到目标系统，这是一个同步（SYN）请求。然后，目标系统将通过同步/应答（SYN/ACK）响应。接下来，源系统将通过应答（ACK）来响应，从而建立起一个通信连接，然后，可以在两个系统之间传输数据。</p><p>TCP SYN 扫描通过执行下面的步骤来进行工作：</p><ol><li>源系统向目标系统发送一个同步请求，该请求中包含一个端口号。</li><li>如果添加在上一步中的所请求的端口号是开启的，那么目标系统将通过同步/应答（SYN/ACK）来响应源系统。</li><li>源系统通过重置（RST）来响应目标系统，从而断开连接。</li><li>目标系统可以通过重置/应答（RST/ACK）来响应源系统。</li></ol><p>这种连接已经开始建立，所以这被认为是半开放连接。因为连接状态是由 NMAP 来管理的，所以你需要有 Root 权限。</p><p>如果被扫描的端口是关闭的，那么将执行下面的步骤：</p><ol><li>源系统发送一个同步（SYN）请求到目标系统，该请求中包含一个端口号。</li><li>目标系统通过重置（RST）响应源系统，因为该端口是关闭的。</li></ol><p>如果目标系统处于防火墙之后，那么 ICMP 传输或响应会被防火墙禁止，此时，会执行下面的步骤：</p><ol><li>源系统发送一个同步（SYN）请求到目标系统，该请求中包含一个端口号。</li><li>没有任何响应，因为请求被防火墙过滤了。</li></ol><p>在这种情况下，端口可能是被过滤、或者可能打开、或者可能没打开。防火墙可以设置禁止指定端口所有包的传出。防火墙可以禁止所有传入某个指定端口的包，因此目标系统不会接收到请求。</p><p><strong>注：</strong>无响应可能发生在一个启用了防火墙的系统上。即使在本地网络，你也可能会发现被过滤的端口。</p><p>我将向 图片１那样执行对单一系统（10.0.0.2）的 TCP SYN 扫描。使用命令 <code>sudo nmap -sS &lt;IP 地址&gt;</code> 来执行扫描。<code>&lt;IP 地址&gt;</code>可以改为一个单一 IP 地址，像图片１那样，也可以使用一组 IP 地址。</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.119/" alt="Figure 01.jpg"></p><p><em>图片１</em></p><p>你可以看到它表明 997 个被过滤端口没有显示在下面。NMAP 找到两个开启的端口：139 和 445 。</p><p><strong>注：</strong>请记住，NMAP 只会扫描绝大多数熟知的 1000 多个端口。以后，我们会介绍可以扫描所有端口或者指定端口的其它扫描。</p><p>该扫描会被 WireShark 俘获，正如图片２所展示的那样。在这儿，你可以看到对目标系统的初始地址解析协议（ARP）请求。在 ARP 请求下面的是一长列到达目标系统端口的 TCP 请求。第 4 行是到达 <code>http-alt</code> 端口（8080）。源系统的端口号为 47128 。正如图片３ 展示的，许多 SYN 请求只有在做出响应以后才会发送。</p><p><img src="https://www.linuxforum.com/attachments/figure-2-jpg.120/" alt="Figure 2.jpg"></p><p><em>图片２</em></p><p><img src="https://www.linuxforum.com/attachments/figure-3-jpg.121/" alt="Figure 3.jpg"></p><p><em>图片３</em></p><p>在图片３的第 50 行和第 51 行，你可以看到，重置（RST）包被发送给了目标系统。第 53 行和第 55 行显示目标系统的 RST/ACK（重置/应答）。第 50 行是针对 ‘microsoft-ds’ 端口（445），第 51 行是针对 ‘netbios-ssn’ 端口（135），我们可以看到，这两个端口都是打开的。（LCTT 译注：在 50 行和 51 行之前，目标系统发回了 SYN/ACK 响应，表示端口打开。）除了这些端口，没有其他 ACK（应答）是来自目标系统的。每一个请求均可发送超过 1000 次。</p><p>正如图片４所展示的，目标系统是 Windows 系统，我关闭了系统防火墙，然后再次执行扫描。现在，我们看到了 997 个已关闭端口不是 997 个被过滤端口。目标系统上的 135 端口之前被防火墙禁止了，现在也是开启的。</p><p><img src="https://www.linuxforum.com/attachments/figure-04-jpg.122/" alt="Figure 04.jpg"></p><p><em>图片４</em></p><h3 id="tcp-connect-扫描-st" tabindex="-1">TCP Connect() 扫描 （-sT） <a class="header-anchor" href="#tcp-connect-扫描-st" aria-label="Permalink to “TCP Connect() 扫描 （-sT）”">​</a></h3><p>尽管 TCP SYN 扫描需要 Root 权限，但 TCP Connect() 扫描并不需要。在这种扫描中会执行一个完整的“三次握手”。因为不需要 Root 权限，所以在无法获取 Root 权限的网络上，这种扫描非常有用。</p><p>TCP Connect() 扫描的工作方式也是执行“三次握手”。正如上面描述过的，“三次握手”发生在两个系统之间。源系统发送一个同步（SYN）请求到目标系统。然后，目标系统将通过同步／应答（SYN/ACK）来响应。最后，源系统通过应答（ACK）来响应，从而建立起连接，然后便可在两个系统之间传输数据。</p><p>TCP Connect 扫描通过执行下面的步骤来工作：</p><ol><li>源系统发送一个同步（SYN）请求到目标系统，该请求中包含一个端口号。</li><li>如果上一步所请求的端口是开启的，那么目标系统将通过同步/应答（SYN/ACK）来响应源系统。</li><li>源系统通过应答（ACK）来响应目标系统从而完成会话创建。</li><li>然后，源系统向目标系统发送一个重置（RST）包来关闭会话。</li><li>目标系统可以通过同步/应答（SYN/ACK）来响应源系统。</li></ol><p>若步骤 2 执行了，那么源系统就知道在步骤 1 中的指定端口是开启的。</p><p>如果端口是关闭的，那么会发生和 TCP SYN 扫描相同的事。在步骤 2 中，目标系统将会通过一个重置（RST）包来响应源系统。</p><p>可以使用命令 <code>nmap -sT &lt;IP 地址&gt;</code> 来执行扫描。<code>&lt;IP 地址&gt;</code>可以改为一个单一 IP 地址，像图片５那样，或者使用一组 IP 地址。</p><p>TCP Connect() 扫描的结果可以在图片５中看到。在这儿，你可以看到，有两个已开启端口：139 和 445，这和 TCP SYN 扫描的发现一样。端口 80 是关闭的。剩下没有显示的端口是被过滤了的。</p><p><img src="https://www.linuxforum.com/attachments/figure-05-jpg.123/" alt="Figure 05.jpg"></p><p><em>图片５</em></p><p>让我们关闭防火墙以后再重新扫描一次，扫描结果展示在图片６中。</p><p><img src="https://www.linuxforum.com/attachments/figure-06-jpg.124/" alt="Figure 06.jpg"></p><p><em>图片６</em></p><p>关闭防火墙以后，我们可以看到，更多的端口被发现了。就和 TCP SYN 扫描一样，关闭防火墙以后，发现 139 端口和 445 端口是开启的。我们还发现，端口 2869 也是开启的。也发现有 996 个端口是关闭的。现在，端口 80 是 996 个已关闭端口的一部分 — 不再被防火墙过滤。</p><p>在一些情况下， TCP Connect() 扫描可以在一个更短的时间内完成。和 TCP SYN 扫描相比，TCP Connect() 扫描也可以找到更多的已开启端口</p><hr>',44)),n("p",null,[t[7]||(t[7]=o("via: ",-1)),e(p,{href:"https://www.linuxforum.com/threads/nmap-common-scans-part-two.3879/"},{default:l(()=>[...t[6]||(t[6]=[o("https://www.linuxforum.com/threads/nmap-common-scans-part-two.3879/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=o("作者：",-1)),e(p,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:l(()=>[...t[8]||(t[8]=[o("Jarret",-1)])]),_:1}),t[12]||(t[12]=o(" 译者：",-1)),e(p,{href:"https://github.com/ucasFL"},{default:l(()=>[...t[9]||(t[9]=[o("ucasFL",-1)])]),_:1}),t[13]||(t[13]=o(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原创编译，",-1)),e(p,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[o("Linux中国",-1)])]),_:1}),t[18]||(t[18]=o(" 荣誉推出",-1))])])}const A=i(P,[["render",C]]);export{w as __pageData,A as default};
